export function listIssues(issues, { status, query } = {}) {
  const needle = (query ?? '').trim().toLowerCase();

  return issues.filter(issue =>
    (!status || issue.status === status) &&
    (!needle || issue.title.toLowerCase().includes(needle))
  );
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { issues } from '../initial-data.mjs';
import { listIssues } from './load-implementation.mjs';

const ids = rows => rows.map(row => row.id);

test('ISS-101 normalizes both owner names, matches the whole name and preserves order', () => {
  assert.deepEqual(ids(listIssues(issues, { assignee: ' lIn ' })), ['T-08', 'T-03', 'T-07']);
});

test('ISS-101 trims tabs and full-width spaces on both sides', () => {
  assert.deepEqual(ids(listIssues(issues, { assignee: '\tLIN\u3000' })), ['T-08', 'T-03', 'T-07']);
});

test('ISS-101 returns an empty list when no issue has that owner', () => {
  assert.deepEqual(ids(listIssues(issues, { assignee: 'Unknown' })), []);
});

test('ISS-103 combines owner, status and title by intersection', () => {
  const filters = Object.freeze({ assignee: 'LIN', status: 'open', query: ' cAcHe ' });
  const result = listIssues(issues, filters);
  assert.deepEqual(ids(result), ['T-08']);
  assert.equal(result[0], issues[0]);
  assert.notEqual(result, issues);
});

const variant = process.env.SDD_IMPLEMENTATION ?? 'after';
if (!['before', 'after'].includes(variant)) throw new Error('SDD_IMPLEMENTATION must be before or after');

export const { listIssues } = await import(`../${variant}/list.mjs`);

import assert from 'node:assert/strict';
import test from 'node:test';
import { issues } from '../initial-data.mjs';
import { listIssues } from './load-implementation.mjs';

const ids = rows => rows.map(row => row.id);

test('ISS-102 omitted and blank owners keep every issue, including unassigned issues', () => {
  for (const filters of [{}, { assignee: null }, { assignee: '' }, { assignee: '\t\u3000 ' }]) {
    assert.deepEqual(listIssues(issues, filters), issues);
  }
  const result = listIssues(issues);
  assert.deepEqual(result, issues);
  assert.notEqual(result, issues);
  assert.equal(result[0], issues[0]);
});

test('ISS-103 status is exact and title search is case insensitive', () => {
  assert.deepEqual(ids(listIssues(issues, { status: 'open', query: ' CACHE ' })), ['T-08', 'T-11', 'T-01']);
  assert.deepEqual(listIssues(issues, { status: 'Open' }), []);
});

test('ISS-103 title-only search and empty result behavior stay compatible', () => {
  assert.deepEqual(ids(listIssues(issues, { query: 'efresh' })), ['T-03']);
  assert.deepEqual(listIssues(issues, { query: 'not present' }), []);
  assert.deepEqual(listIssues([], { status: 'open' }), []);
});

const records = [
  { id: 'T-08', title: 'Cache warm-up', status: 'open', assignee: ' Lin ', labels: ['infra', 'infra'] },
  { id: 'T-03', title: 'Cache refresh', status: 'done', assignee: 'LIN', labels: ['infra'] },
  { id: 'T-11', title: 'Cache timeout', status: 'open', assignee: 'Lina', labels: ['infra', 'urgent'] },
  { id: 'T-01', title: 'Cache metrics', status: 'open', assignee: null, labels: ['observability'] },
  { id: 'T-07', title: 'Review errors', status: 'open', assignee: '\u3000lin\t' },
  { id: 'T-14', title: 'Improve index', status: 'open' },
];

export const issues = Object.freeze(records.map(issue => Object.freeze(issue)));
